import React, { useEffect, useState } from "react";

function Dashboard() {
  const [resumes, setResumes] = useState([]);
  const [loading, setLoading] = useState(true);

  // 🔒 PROTECT ROUTE + LOAD DATA
  useEffect(() => {
    const token = localStorage.getItem("token");

    if (!token) {
      window.location.href = "/login";
      return;
    }

    fetchResumes();
  }, []);

  // 📦 FETCH RESUMES
  const fetchResumes = async () => {
    try {
      const token = localStorage.getItem("token");

      const res = await fetch("http://localhost:5000/api/resume/my", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      const data = await res.json();
      setResumes(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  // ❌ DELETE
  const handleDelete = async (id) => {
    try {
      const token = localStorage.getItem("token");

      await fetch(`http://localhost:5000/api/resume/${id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      fetchResumes();
    } catch (err) {
      console.error(err);
    }
  };

  // 🚪 LOGOUT
  const handleLogout = () => {
    localStorage.removeItem("token");
    window.location.href = "/login";
  };

  return (
    <div style={styles.container}>
      {/* HEADER */}
      <div style={styles.header}>
        <h2>Your Saved Resumes</h2>

        <div>
          <button
            onClick={() => (window.location.href = "/")}
            style={styles.analyzeBtn}
          >
            Analyze Resume
          </button>

          <button onClick={handleLogout} style={styles.logoutBtn}>
            Logout
          </button>
        </div>
      </div>

      {/* CONTENT */}
      {loading ? (
        <p>Loading...</p>
      ) : resumes.length === 0 ? (
        <p>No resumes found</p>
      ) : (
        resumes.map((r) => (
          <div key={r._id} style={styles.card}>
            <h3>ATS Score: {r.score}</h3>

            <p style={styles.text}>
              {r.optimizedText?.substring(0, 300)}...
            </p>

            <button
              onClick={() => handleDelete(r._id)}
              style={styles.deleteBtn}
            >
              Delete
            </button>
          </div>
        ))
      )}
    </div>
  );
}

// 🎨 STYLES
const styles = {
  container: {
    padding: "30px",
    color: "white",
  },
  header: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    marginBottom: "20px",
  },
  analyzeBtn: {
    marginRight: "10px",
    padding: "8px 15px",
    background: "#007bff",
    color: "white",
    border: "none",
    cursor: "pointer",
  },
  logoutBtn: {
    padding: "8px 15px",
    background: "red",
    color: "white",
    border: "none",
    cursor: "pointer",
  },
  card: {
    background: "#111",
    padding: "20px",
    marginBottom: "15px",
    borderRadius: "10px",
  },
  text: {
    marginTop: "10px",
  },
  deleteBtn: {
    marginTop: "10px",
    background: "orange",
    border: "none",
    padding: "8px 12px",
    cursor: "pointer",
  },
};

export default Dashboard;
